// Example Maven or Gradle settings.xml / build.gradle snippet for secure Artifactory/Nexus integration
allprojects {
    repositories {
        maven {
            url "https://repo.enterprise.internal/artifactory/libs-release"
            credentials {
                username = System.getenv('ARTIFACTORY_USER')
                password = System.getenv('ARTIFACTORY_TOKEN')
            }
        }
    }
}
